 \foreach \cellPosition in {\row} {
  \ifthenelse{\isempty{\currRow}}
  {% if \currRow is empty, start a new row
   \appendtoks \cellPosition \to \currRow
   \global\def\currRow{\currRow}
   }%
   {% otherwise, append the cell position to the current row
   \appendtoks \cellPosition\to\currRow
   }%
 }
